package com.biocircular.reportes.controller; import com.biocircular.reportes.dto.*; import com.biocircular.reportes.service.ReportService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/reportes") public class ReportController {private final ReportService s;public ReportController(ReportService x){s=x;}@GetMapping("/dashboard")DashboardDto dashboard(@Valid ReportFilterDto f){return s.dashboard(f);}@GetMapping("/clientes")List<Map<String,Object>> clientes(@Valid ReportFilterDto f){return s.data("clientes",f);}@GetMapping("/recolecciones")List<Map<String,Object>> recolecciones(@Valid ReportFilterDto f){return s.data("recolecciones",f);}@GetMapping("/rutas")List<Map<String,Object>> rutas(@Valid ReportFilterDto f){return s.data("rutas",f);}@GetMapping("/compostaje")List<Map<String,Object>> compostaje(@Valid ReportFilterDto f){return s.data("compostaje",f);}@GetMapping("/inventario")List<Map<String,Object>> inventario(@Valid ReportFilterDto f){return s.data("inventario",f);}@GetMapping("/indicadores")DashboardDto indicadores(@Valid ReportFilterDto f){return s.dashboard(f);}@GetMapping("/resumen")DashboardDto resumen(@Valid ReportFilterDto f){return s.dashboard(f);}@GetMapping("/pdf")ResponseEntity<byte[]> pdf(@RequestParam String type,@Valid ReportFilterDto f){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=reporte.pdf").contentType(MediaType.APPLICATION_PDF).body(s.pdf(type,f));}@GetMapping("/excel")ResponseEntity<byte[]> excel(@RequestParam String type,@Valid ReportFilterDto f){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=reporte.xlsx").contentType(MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).body(s.excel(type,f));}}
